import{_ as t,o as c,c as g,a3 as h}from"./chunks/framework.DX_KL3e0.js";const p=JSON.parse('{"title":"Đa Công Ty","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/da-cong-ty.md","filePath":"chuc-nang/da-cong-ty.md","lastUpdated":1781776545000}'),o={name:"chuc-nang/da-cong-ty.md"};function i(a,n,r,s,u,l){return c(),g("div",null,[...n[0]||(n[0]=[h('<h1 id="đa-cong-ty" tabindex="-1">Đa Công Ty <a class="header-anchor" href="#đa-cong-ty" aria-label="Permalink to &quot;Đa Công Ty&quot;">​</a></h1><p>FADO AssetFlow hỗ trợ <strong>một tài khoản làm việc ở nhiều công ty</strong> trong cùng một tập đoàn. Người dùng có <strong>một công ty chính</strong> (gán mặc định khi tạo tài khoản) và có thể được bật làm việc thêm ở <strong>các công ty phụ</strong> — mỗi công ty có vai trò, phòng ban, vị trí và quyền riêng.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Chuyển công ty đang xem:</strong> dùng <strong>bộ chuyển công ty</strong> ở Topbar (ngay cạnh menu người dùng).</li><li><strong>Cấu hình công ty phụ:</strong> trong cửa sổ chỉnh sửa người dùng → tab <strong>🏢 Đa Công Ty</strong> (chỉ Quản trị viên / Quản trị tối cao).</li><li><strong>Mọi danh sách, báo cáo, thông báo</strong> đều được lọc theo công ty đang chọn ở Topbar.</li></ul></div><h2 id="bo-chuyen-cong-ty-tren-topbar" tabindex="-1">Bộ chuyển công ty trên Topbar <a class="header-anchor" href="#bo-chuyen-cong-ty-tren-topbar" aria-label="Permalink to &quot;Bộ chuyển công ty trên Topbar&quot;">​</a></h2><p>Nếu tài khoản được bật ở ≥ 2 công ty, Topbar hiển thị tên công ty đang xem kèm mũi tên thả xuống. Bấm để đổi công ty đang xem — toàn bộ dữ liệu hiển thị (tài sản, công việc, hồ sơ, đặt phòng, ticket…) chuyển sang phạm vi công ty đã chọn ngay lập tức, không cần đăng nhập lại.</p><div class="tip custom-block"><p class="custom-block-title">Công ty đang chọn được nhớ ở trình duyệt</p><p>Lần đăng nhập tiếp theo bạn mở lại đúng công ty đã chọn lần trước. Nếu công ty đó không còn được bật cho bạn, hệ thống tự đổi về công ty chính.</p></div><h2 id="cau-hinh-cong-ty-phu-quan-tri-vien" tabindex="-1">Cấu hình công ty phụ (Quản trị viên) <a class="header-anchor" href="#cau-hinh-cong-ty-phu-quan-tri-vien" aria-label="Permalink to &quot;Cấu hình công ty phụ (Quản trị viên)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Ai làm được?</p><ul><li><strong>Quản trị tối cao</strong> — có thể bật ở <strong>bất kỳ công ty nào</strong>.</li><li><strong>Quản trị viên</strong> — bật được theo phạm vi quản lý của mình.</li><li><strong>Quản lý / Người dùng</strong> — không sửa được, chỉ chuyển giữa các công ty đã được bật.</li></ul></div><p>Mở menu Quản lý người dùng → chọn một người dùng → mở tab <strong>🏢 Đa Công Ty</strong>. Tab này không hiển thị khi tài khoản đang chỉnh sửa chưa có <strong>Công ty chính</strong> (gán ở tab Thông Tin trước).</p><p>Với mỗi công ty muốn bật làm công ty phụ, bạn cấu hình:</p><table tabindex="0"><thead><tr><th>Trường</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td><strong>Vai trò</strong></td><td>Vai trò áp dụng trong công ty này (có thể khác công ty chính).</td></tr><tr><td><strong>Phòng ban / Bộ phận</strong></td><td>Cây tổ chức tại công ty đó.</td></tr><tr><td><strong>Vị trí</strong></td><td>Vị trí công việc tại công ty.</td></tr><tr><td><strong>Quản lý trực tiếp</strong></td><td>Người quản lý của người này trong công ty đó.</td></tr><tr><td><strong>Quyền module</strong></td><td>Tùy biến quyền chi tiết (tuỳ chọn — mặc định theo vai trò).</td></tr></tbody></table><p>Bấm <strong>Lưu</strong> — tài khoản đó ngay lập tức thấy công ty mới trong bộ chuyển ở Topbar.</p><div class="info custom-block"><p class="custom-block-title">Công ty chính</p><p>Công ty chính được gán ở tab <strong>Thông Tin</strong> và <strong>không xuất hiện ở tab Đa Công Ty</strong>. Để đổi công ty chính, đổi ở tab Thông Tin — các công ty phụ khác giữ nguyên.</p></div><h2 id="pham-vi-du-lieu-theo-cong-ty-đang-chon" tabindex="-1">Phạm vi dữ liệu theo công ty đang chọn <a class="header-anchor" href="#pham-vi-du-lieu-theo-cong-ty-đang-chon" aria-label="Permalink to &quot;Phạm vi dữ liệu theo công ty đang chọn&quot;">​</a></h2><p>Khi bạn chọn một công ty ở Topbar, hầu hết module tự lọc theo công ty đó:</p><ul><li><strong>Tài sản, Tổ chức, Nhân sự, Hồ sơ, Đánh giá</strong> — chỉ hiện dữ liệu thuộc công ty.</li><li><strong>Công việc, Tickets</strong> — chỉ hiện do/giao cho người trong công ty.</li><li><strong>Đặt phòng họp</strong> — chỉ phòng &amp; lượt đặt thuộc công ty.</li><li><strong>Báo cáo Công việc</strong> — đối tượng có thể chọn lọc theo công ty bạn đang xem (xem <a href="/help/chuc-nang/cong-viec.html#xuất-báo-cáo">Báo cáo Công việc</a>).</li></ul><div class="tip custom-block"><p class="custom-block-title">Không thấy dữ liệu quen thuộc?</p><p>Trước tiên kiểm tra công ty đang chọn ở Topbar — chuyển công ty trước khi báo lỗi mất dữ liệu.</p></div><h2 id="chuyen-cong-ty-đoi-han-vai-tro" tabindex="-1">Chuyển công ty = đổi hẳn vai trò <a class="header-anchor" href="#chuyen-cong-ty-đoi-han-vai-tro" aria-label="Permalink to &quot;Chuyển công ty = đổi hẳn vai trò&quot;">​</a></h2><p>Đây là nguyên tắc quan trọng nhất của chế độ đa công ty: <strong>vai trò của bạn được xét tại công ty bạn đang đứng</strong>, không phải vai trò ở công ty chính.</p><p>Khi bạn chuyển sang một công ty phụ, bạn <strong>thoát hẳn vai</strong> ở công ty chính. Vai trò, quyền module, phòng ban và cả <strong>phạm vi dữ liệu được nhìn thấy</strong> đều lấy theo công ty mới.</p><p>Ví dụ dễ hiểu: một người là <strong>Super Admin</strong> ở FADO Group nhưng chỉ là <strong>Admin</strong> ở công ty con. Khi người đó chuyển sang công ty con:</p><ul><li>Vai hiệu lực là <strong>Admin</strong> (Topbar hiển thị đúng vai này).</li><li>Trong module <strong>Tổ chức</strong>, họ <strong>chỉ thấy đúng công ty con đó</strong> — không thấy công ty chính, cũng không thấy công ty nào khác trong tập đoàn.</li><li>Ngược lại, khi đứng ở công ty mà vai của họ <strong>vẫn là Super Admin</strong>, họ mới thấy toàn bộ các công ty.</li></ul><div class="warning custom-block"><p class="custom-block-title">Tạo dữ liệu mới sẽ vào công ty đang đứng</p><p>Khi bạn thêm <strong>phòng ban, chức vụ, vị trí công việc</strong>… mà không chỉ định công ty, dữ liệu sẽ được tạo trong <strong>công ty bạn đang chọn ở Topbar</strong>. Hãy kiểm tra Topbar trước khi thêm mới, tránh tạo nhầm sang công ty khác.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi đăng nhập rồi mà không thấy bộ chuyển công ty ở Topbar?</strong> Tài khoản của bạn chỉ thuộc một công ty. Yêu cầu Quản trị viên bật thêm công ty cho bạn ở tab Đa Công Ty.</p><p><strong>Mỗi công ty tôi có quyền khác nhau không?</strong> Có. Vai trò và quyền module được cấu hình riêng cho từng công ty. Ví dụ: bạn là Quản lý ở công ty A nhưng chỉ là Người dùng ở công ty B.</p><p><strong>Đổi công ty đang xem có ảnh hưởng người khác không?</strong> Không. Lựa chọn này lưu cục bộ ở trình duyệt của bạn, không ảnh hưởng người dùng khác.</p><p><strong>Tôi là Super Admin, sao chuyển sang công ty con lại không thấy các công ty khác nữa?</strong> Đúng như thiết kế. Vai trò được xét theo công ty bạn đang đứng: ở công ty con bạn chỉ là Admin, nên chỉ thấy công ty đó. Muốn quản trị toàn tập đoàn, hãy chuyển về công ty mà vai của bạn là Super Admin.</p><p><strong>Tôi là Giám đốc ở công ty con, vì sao vẫn hiện tên quản lý bên công ty chính?</strong> Mỗi công ty có <strong>phân công riêng</strong> kèm người quản lý riêng. Vào hồ sơ nhân sự → tab <strong>Phân Công</strong> → sửa phân công tại công ty con và để trống (hoặc chọn đúng) ô Quản lý.</p><hr><p><em>Liên quan:</em> <a href="/help/quan-tri/nguoi-dung.html">Người dùng &amp; phân quyền</a> · <a href="/help/quan-tri/co-cau-to-chuc.html">Cơ cấu tổ chức</a></p>',31)])])}const e=t(o,[["render",i]]);export{p as __pageData,e as default};
